"„Die Mauer hält die Monster draußen. Solange du drinnen bist, bist du sicher.“": "«La muralla mantiene fuera a los monstruos. Mientras estés dentro, estás a salvo.»",
"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "«Los jabalíes se me comen los nabos. Si ves alguno, ¡dale caza!»",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "«¿Has visto alguna vez un dragón? Lian dice que en el Monte de Fuego hay.»",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "«Antes Kazehana era una ciudad tranquila. Luego llegaron las piedras.»",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "«Cada piedra tiene su propia alma. Y cada una deja algo distinto.»",
