"Stadt · sicherer Ort": "Ciudad · lugar seguro",
"Lager · sicherer Ort": "Campamento · lugar seguro",
"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "La gran ciudad de Kazehana con los verdes Prados del Sol.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Denso bosque de coníferas con bandidos, arañas y osos. Cueva de las Arañas y Sótano de los Bandidos.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Valle polvoriento de orcos y escorpiones. Fortaleza Orca.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Gris llanura de ceniza con ogros y demonios. Cripta de los Muertos.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "Cumbres heladas con lobos de hielo, yetis y espíritus de escarcha. Gruta de Hielo.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Pantano brumoso lleno de no muertos, brujas y gules.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Basalto negro y ríos de lava, gólems, demonios de fuego y dragones. Guarida del Dragón.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Giras sobre ti mismo, golpeas a todos los enemigos cercanos y los aturdes brevemente.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Bufo: rayos chisporrotean a tu alrededor. Más vel. de ataque y de movimiento.",
"Erdbeben": "Terremoto",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Pisas con fuerza y el suelo tiembla: todos los enemigos a tu alrededor quedan aturdidos {0} s.",
"Starker Körper": "Cuerpo Fuerte",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Bufo: tu cuerpo se vuelve duro como la piedra. Más defensa y menos daño recibido.",
"Geistesschlag": "Golpe Espiritual",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Un golpe concentrado con toda tu fuerza sobre un solo objetivo. Daño muy alto.",
"Kriegsschrei": "Grito de Guerra",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Un grito que paraliza a los enemigos: se ralentizan y reciben más daño.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "Giras con ambas dagas y golpeas a todos los enemigos a tu alrededor.",
"Schattensprung": "Salto Sombrío",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Saltas a través de las sombras hacia delante y cortas todo a tu paso.",
"Lähmende Klinge": "Hoja Paralizante",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Un corte en los tendones: el objetivo queda aturdido {0} s y envenenado {1} s.",
"Schattenmantel": "Manto de Sombras",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Bufo: las sombras te envuelven. Más evasión y más golpes críticos.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Bufo: la fuerza del dragón fluye en ti. Más ataque y más daño de habilidad.",
"Geisterfaust": "Puño Espiritual",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Un puño de energía espiritual golpea a un objetivo y lo aturde {0} s.",
"Windfessel": "Grilletes de Viento",
"Wirbelnder Wind fesselt Gegner um dich: Sie werden langsamer und verwundbar.": "Un viento arremolinado atrapa a los enemigos a tu alrededor: se ralentizan y son vulnerables.",
"Segen": "Bendición",
"Buff: Weniger erlittener Schaden, Leben regeneriert sich, mehr kritische Treffer.": "Bufo: menos daño recibido, la vida se regenera, más golpes críticos.",
"Heilung": "Curación",
"Heilt einen Teil deines Lebens und gibt dir danach mehr Angriff.": "Cura parte de tu vida y después te da más ataque.",
