"Füchse im Hühnerstall": "Zorros en el gallinero",
"Der erste Seelenstein": "La primera piedra de alma",
"Wolfsplage": "Plaga de lobos",
"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen.": "Los lobos se vuelven más osados. Diezma la manada antes de que lleguen a la puerta.",
"Verirrte Hirsche": "Ciervos extraviados",
"Der Alpha": "El alfa",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel.": "Tras los lobos están sus líderes, los lobos alfa. Sin ellos, la manada se desmorona.",
"Keiler in den Rüben": "Jabalíes en los nabos",
"Stein der Wut": "Piedra de la Ira",
"Auf in den Dunkelwald": "Rumbo al Bosque Oscuro",
"Banditen im Dunkelwald": "Bandidos en el Bosque Oscuro",
"Kapitel {0} · Dunkelwald": "Capítulo {0} · Bosque Oscuro",
"Schützen im Dickicht": "Tiradores en la espesura",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter.": "Desde las copas de los árboles, los bandidos disparan a todo lo que se mueve. Bájalos.",
"Netz der Spinnen": "Red de arañas",
"Stein der Gier": "Piedra de la Codicia",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie.": "Dos Piedras de la Codicia atraen a los bandidos como el oro a los ladrones. Destrúyelas.",
"Lautlose Jäger": "Cazadores silenciosos",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie.": "Los linces despedazan a nuestros exploradores sin que nadie los vea venir. Sé más atento que ellos.",
"Der Banditenfürst": "El señor de los bandidos",
"Der Braunbär": "El oso pardo",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig.": "Una manada de osos pardos ocupa el camino de los leñadores. Son fuertes, ten cuidado.",
"Stein der Dornen": "Piedra de las Espinas",
"Krieg in der Rostschlucht": "Guerra en el Garganta Herrumbrosa",
"Orks vor der Talwacht": "Orcos ante la Guardia del Valle",
