"Hyänen der Orks": "Hienas de los orcos",
"Die Schamanen": "Los chamanes",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut.": "Sus chamanes lanzan maldiciones sobre el valle. Sin ellos, los orcos pierden el valor.",
"Stein der Schwärze": "Piedra de la Negrura",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen.": "Los orcos adoran piedras negras. Arrebátales sus ídolos.",
"Stachel im Sand": "Aguijón en la arena",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten.": "En las grietas anidan escorpiones gigantes. Su veneno paraliza a un buey. Limpia las grietas.",
"Der Ork-Hauptmann": "El capitán orco",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie.": "Sin sus capitanes, los orcos son solo una horda salvaje. Encuéntralos.",
"Stein der Asche": "Piedra de la Ceniza",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt.": "La Piedra de la Ceniza quema el valle desde dentro. Apágala antes de que solo quede polvo.",
"Asche über dem Ödland": "Ceniza sobre las Tierras Baldías",
"Oger im Aschenfeld": "Ogros en el campo de ceniza",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern.": "Thrak hizo bien en enviarte. Los ogros saquean nuestro campamento cada noche. Mantenlos alejados.",
"Kapitel {0} · Ödland": "Capítulo {0} · Tierras Baldías",
"Wargrudel": "Manada de huargos",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel.": "Los huargos siguen a los ogros y comen lo que estos dejan. Caza a la manada.",
"Dämonen im Ödland": "Demonios en las Tierras Baldías",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe.": "De las grietas de las Tierras Baldías salen demonios. Devuélvelos a las profundidades.",
"Stein der Glut": "Piedra de la Brasa",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus.": "Las Piedras de la Brasa hacen arder las Tierras Baldías. Apágalas.",
"Höllenhunde": "Perros infernales",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen.": "Perros de tres cabezas vigilan las grietas. Quien los venza podrá acercarse a ellas.",
"Die Oase im Süden": "El oasis del sur",
"Kobras in der Wüste": "Cobras en el desierto",
"Kapitel {0} · Schlangental": "Capítulo {0} · Valle de las Serpientes",
"Das Rasseln im Sand": "El cascabeleo en la arena",
"Stein der Schatten": "Piedra de la Sombra",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder.": "En la jungla, las pitones estrangulan bueyes enteros. Quien corta leña allí no vuelve.",
"Schwarze Panther": "Panteras negras",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher.": "Las panteras de los naga cazan de noche. Haz que la jungla vuelva a ser segura.",
"Eis im Norden": "Hielo en el norte",
"Eiswölfe": "Lobos de hielo",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche.": "¿Te envía Hakim? Bien. Los lobos de hielo rodean nuestro campamento, huelen cualquier debilidad.",
"Kapitel {0} · Frostgipfel": "Capítulo {0} · Cumbre Helada",
"Der Yeti": "El yeti",
"Stein des Frostes": "Piedra de la Escarcha",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie.": "Dos Piedras de la Escarcha impiden que la cumbre se deshiele. Destrúyelas.",
"Wilde Mammuts": "Mamuts salvajes",
"Frostgeister": "Espíritus de escarcha",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen.": "En las ventiscas vagan espíritus. Quien los toca se congela por dentro.",
"Stein der Stille": "Piedra del Silencio",
"Der Eiskönig": "El Rey de hielo",
"Alles Eis gehorcht dem Eiskönig in der Eisgrotte. Bezwinge ihn, dann taut der Gipfel.": "Todo el hielo obedece al Rey de hielo de la Gruta de Hielo. Derrótalo y la cumbre se deshelará.",
"Nebel über dem Moor": "Niebla sobre el pantano",
"Das Totenmoor": "El Pantano de los Muertos",
"Kapitel {0} · Totenmoor": "Capítulo {0} · Pantano de los Muertos",
"Moorwölfe": "Lobos del pantano",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest.": "Aquí los lobos están medio muertos y no dejan de cazar. Remátalos.",
"Die Sumpfhexen": "Las brujas del pantano",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu.": "Las brujas invocan a los muertos desde el fango. Sin ellas, las tumbas seguirán cerradas.",
"Stein der Fäulnis": "Piedra de la Podredumbre",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr.": "Dos Piedras de la Podredumbre envenenan el agua. Ya no crece nada vivo.",
"Ghule": "Gules",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller.": "Los gules devoran lo que las brujas despiertan. Son rápidos y hambrientos. Sé más rápido.",
"Donner in der Klamm": "Trueno en el desfiladero",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke.": "¿Te envía Oswin? Los troles asedian el desfiladero. Muéstrales nuestra fuerza.",
"Kapitel {0} · Donnerklamm": "Capítulo {0} · Desfiladero del Trueno",
"Harpyien": "Arpías",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft.": "Las arpías se lanzan sobre todo el que sube al paso. Derríbalas.",
"Die Minotauren": "Los minotauros",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf.": "Los minotauros embisten nuestras puertas con los cuernos bajos. Detenlos.",
"Stein der Pein": "Piedra del Tormento",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz.": "Piedras rojo sangre brotan de las rocas. Se alimentan del dolor.",
"Erwachte Titanen": "Titanes despertados",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer.": "En la Cresta de los Titanes se alzan los titanes de piedra. Haz que vuelvan a quedarse quietos, para siempre.",
"Der Berg brennt": "La montaña arde",
"Lavagolems": "Gólems de lava",
"Gunhild schickt dich? Dann bist du bereit. Golems aus Lava wälzen sich auf unser Lager zu.": "¿Te envía Gunhild? Entonces estás listo. Gólems de lava avanzan hacia nuestro campamento.",
"Kapitel {0} · Feuerberg": "Capítulo {0} · Monte de Fuego",
"Glutkatzen": "Gatos de brasa",
"Glutkatzen streifen durch die Lavafelder. Wo sie laufen, brennt der Boden.": "Los gatos de brasa merodean por los campos de lava. Por donde pasan, el suelo arde.",
"Stein der Flamme": "Piedra de la Llama",
"Zwei Steine der Flamme heizen den Berg an. Ohne sie verlöschen die Lavaflüsse.": "Dos Piedras de la Llama calientan la montaña. Sin ellas, los ríos de lava se apagan.",
"Feuerdämonen": "Demonios de fuego",
"Aus den Kratern steigen Feuerdämonen. Treib sie zurück ins Feuer.": "De los cráteres salen demonios de fuego. Devuélvelos al fuego.",
"Feuerdrachen": "Dragones de fuego",
"Am Feuerberg nisten Drachen. Wenn sie flügge werden, ist kein Dorf mehr sicher.": "En el Monte de Fuego anidan dragones. Cuando echen a volar, ningún pueblo estará a salvo.",
"Stein des Untergangs": "Piedra de la Perdición",
"Heimkehr nach Kazehana": "Regreso a Kazehana",
