"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Apenas se fueron los perros, los zorros rondan los establos. Échalos de vuelta a los prados",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "Los jabalíes se comen la cosecha de los campesinos. Un invierno sin provisiones sería nuestro fin",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Al borde de los prados brilla una piedra de ira. Su furia enloquece a los animales – rómpela",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Menos mal que Bao te envía. Bandidos asaltan a cada comerciante en el camino del bosque. Expúlsalos",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "Los jabalíes de aquí tienen espinas en vez de cerdas. Destrozan nuestras trampas – y a los tramperos",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "En lo profundo del bosque, arañas gigantes tejen redes sobre los caminos. Quémalas si hace falta",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "En medio del bosque crece una piedra de espinas. Sus zarzas asfixian cada árbol. Destrúyela",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "¿Te envía Hagen? Entonces ven, los orcos ya están ante nuestras empalizadas. Debilita su ejército",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Los orcos crían hienas como perros y las azuzan contra nuestros exploradores. Acaba con la jauría",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "¿Te envía Idris? Los dioses son buenos con Sahra. Las cobras acechan en cada abrevadero",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "¿Oyes ese cascabeleo? Serpientes de cascabel. Cientos. Las caravanas ya no se atreven a salir",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "En el Pico Helado han visto yetis tan grandes como casas. Trae sus pieles como prueba",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "Los mamuts están furiosos desde que el frío no cede. Pisotean nuestras cabañas de provisiones",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Donde se alza la piedra del silencio, enmudece toda canción. Devuelve el sonido a la cumbre",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "La última y más poderosa de todas las piedras de alma. Destrúyela y las piedras dejarán de crecer",
