"Nachthirsche rennen mit leuchtenden Geweihen gegen unsere Zäune, als jage sie etwas. Halte sie auf": "Ciervos nocturnos con cornamentas brillantes embisten nuestras vallas, como si algo los persiguiera. Detenlos",
"Die Leitwölfe": "Los líderes de manada",
"Jedes Nebelrudel folgt einem Nachtleitwolf. Ohne ihn zerstreut sich das Rudel im Dunst": "Cada manada de la niebla sigue a un líder nocturno. Sin él, la manada se dispersa en la bruma",
