"Die Keiler hier tragen Glut im Borstenkamm. Wo sie sich reiben, fängt das Unterholz Feuer": "Los jabalíes de aquí llevan brasas en la cresta. Donde se rozan, el sotobosque se incendia",
"Schützen im Rauch": "Arqueros en el humo",
"Aus dem Rauch schießen Rußschützen, bevor man sie sieht. Hol sie aus den verbrannten Kronen": "Arqueros de hollín disparan desde el humo antes de que se les vea. Sácalos de las copas quemadas",
"Graue Netze": "Redes grises",
"Zwei Steine der Gier locken die Räuber an wie Glut die Motten. Zerschlage sie": "Dos piedras de la codicia atraen a los bandidos como la brasa a las polillas. Rómpelas",
"Rußgraue Jäger": "Cazadores gris hollín",
"Rußluchse sind in der Asche unsichtbar. Unsere Köhler kommen nicht mehr heim. Sei wachsamer als sie": "Los linces de hollín son invisibles en la ceniza. Nuestros carboneros ya no vuelven. Sé más atento que ellos",
