"Ascan schickt dich? Dann komm, die Beinbrecher stehen schon vor unserem Ring. Brich ihre Reihen": "¿Te envía Ascan? Entonces ven, los rompehuesos ya están ante nuestro anillo. Rompe sus filas",
"Aashyänen": "Hienas carroñeras",
"Die Hyänen folgen den Beinbrechern und fressen, was diese liegen lassen. Erledige die Meute": "Las hienas siguen a los rompehuesos y devoran lo que dejan. Acaba con la jauría",
"Die Knochenruferinnen": "Las invocadoras de huesos",
"Die Ruferinnen singen die Gebeine aus dem Sand. Ohne ihren Gesang bleiben die Toten liegen": "Las invocadoras cantan para sacar los huesos de la arena. Sin su canto, los muertos siguen yaciendo",
"Zwei schwarze Steine ragen aus den Dünen, und die Knochen sammeln sich darum. Nimm ihnen ihre Mitte": "Dos piedras negras sobresalen de las dunas y los huesos se acumulan a su alrededor. Quítales su centro",
